import "server-only";

import { z } from "zod";

export const subscriptionEventTypes = [
  "subscription.active",
  "subscription.renewed",
  "subscription.updated",
  "subscription.past_due",
  "subscription.on_hold",
  "subscription.cancelled",
  "subscription.expired",
  "subscription.failed",
  "subscription.paused",
  "subscription.unpaused",
  "subscription.plan_changed",
  "subscription.update_payment_method",
] as const;
export const billingEventTypes = [
  ...subscriptionEventTypes,
  "payment.succeeded",
  "payment.failed",
  "payment.processing",
  "payment.cancelled",
] as const;
export const subscriptionStatuses = [
  "pending",
  "active",
  "past_due",
  "on_hold",
  "cancelled",
  "expired",
  "failed",
  "paused",
] as const;
const id = z.string().min(1).max(200);
const timestamp = z.iso.datetime({ offset: true });
const metadata = z
  .object({
    mailloopUserId: z.uuid().optional(),
    checkoutAttemptId: z.uuid().optional(),
  })
  .default({});
export const providerSubscriptionSchema = z.object({
  subscription_id: id,
  created_at: timestamp.optional(),
  customer: z.object({ customer_id: id }),
  product_id: id,
  status: z.enum(subscriptionStatuses),
  previous_billing_date: timestamp,
  next_billing_date: timestamp,
  cancel_at_next_billing_date: z.boolean(),
  currency: z.string().regex(/^[A-Z]{3}$/),
  billing: z.object({ country: z.string().regex(/^[A-Z]{2}$/) }),
  recurring_pre_tax_amount: z.number().int().nonnegative(),
  metadata,
  past_due_ends_at: timestamp.nullish(),
});
export type ProviderSubscription = z.infer<typeof providerSubscriptionSchema>;

export const normalizedSubscriptionSchema = z.object({
  kind: z.literal("subscription"),
  subscription: providerSubscriptionSchema,
});
export const normalizedPaymentSchema = z.object({
  kind: z.literal("payment"),
  paymentId: id,
  customerId: id,
  subscriptionId: id,
  checkoutSessionId: id.nullable(),
  succeeded: z.boolean(),
  status: z.enum(["succeeded", "failed", "processing", "cancelled"]).optional(),
  currency: z.string().regex(/^[A-Z]{3}$/),
  amount: z.number().int().nonnegative(),
  startsAt: timestamp.nullable(),
  endsAt: timestamp.nullable(),
  metadata,
});
export const normalizedBillingSchema = z.discriminatedUnion("kind", [
  normalizedSubscriptionSchema,
  normalizedPaymentSchema,
]);
export type NormalizedBilling = z.infer<typeof normalizedBillingSchema>;

// Explicit allowlists discard customer names, emails, addresses, card data and
// unrelated metadata before anything reaches the durable inbox or Inngest.
export function normalizeBillingEvent(input: unknown) {
  const envelope = z
    .object({ business_id: id, type: z.string(), timestamp, data: z.unknown() })
    .parse(input);
  if (!(billingEventTypes as readonly string[]).includes(envelope.type))
    return null;
  if (envelope.type.startsWith("subscription.")) {
    return {
      ...envelope,
      data: {
        kind: "subscription" as const,
        subscription: providerSubscriptionSchema.parse(envelope.data),
      },
    };
  }
  const payment = z
    .object({
      payment_id: id,
      customer: z.object({ customer_id: id }),
      status: z.string(),
      currency: z.string().regex(/^[A-Z]{3}$/),
      total_amount: z.number().int().nonnegative(),
      is_multi_subscription: z.boolean().optional(),
      is_update_payment_method: z.boolean().optional(),
      subscription_id: id.nullish(),
      subscription_ids: z.array(id).optional(),
      checkout_session_id: id.nullish(),
      service_periods: z
        .array(
          z.object({
            subscription_id: id,
            starts_at: timestamp,
            ends_at: timestamp,
          }),
        )
        .default([]),
      metadata,
    })
    .parse(envelope.data);
  if (payment.is_multi_subscription || payment.is_update_payment_method)
    return null;
  const subscriptionId =
    payment.subscription_id ?? payment.subscription_ids?.[0];
  if (!subscriptionId || (payment.subscription_ids?.length ?? 0) > 1)
    return null;
  const succeeded = envelope.type === "payment.succeeded";
  if (payment.status !== envelope.type.slice("payment.".length))
    throw new Error("Payment status mismatch");
  const period = payment.service_periods.find(
    (p) => p.subscription_id === subscriptionId,
  );
  if (
    succeeded &&
    (!period ||
      payment.total_amount <= 0 ||
      new Date(period.starts_at) >= new Date(period.ends_at))
  )
    throw new Error("Missing settled subscription service period");
  return {
    ...envelope,
    data: {
      kind: "payment" as const,
      paymentId: payment.payment_id,
      customerId: payment.customer.customer_id,
      subscriptionId,
      checkoutSessionId: payment.checkout_session_id ?? null,
      succeeded,
      status: payment.status as
        "succeeded" | "failed" | "processing" | "cancelled",
      currency: payment.currency,
      amount: payment.total_amount,
      startsAt: period?.starts_at ?? null,
      endsAt: period?.ends_at ?? null,
      metadata: payment.metadata,
    },
  };
}
